/* From Uiverse.io by vinodjangid07 - Tags: switch, hamburger, toggle, click effect */
.__UIV_SCOPE__ #checkbox {
  display: none;
}

.__UIV_SCOPE__ .toggle {
  position: relative;
  width: 40px;
  height: 40px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .bars {
  width: 100%;
  height: 4px;
  background-color: rgb(76, 189, 151);
  border-radius: 5px;
  transition-duration: .3s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle .bars {
  margin-left: 13px;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar2 {
  transform: rotate(135deg);
  margin-left: 0;
  transform-origin: center;
  transition-duration: .3s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar1 {
  transform: rotate(45deg);
  transition-duration: .3s;
  transform-origin: left center;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar3 {
  transform: rotate(-45deg);
  transition-duration: .3s;
  transform-origin: left center;
}
